import { test, expect } from '@playwright/test';

test.describe('Unsaved Form Warning', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('about:blank');
    await page.setContent(`
      <form id="testForm">
        <label for="nameInput">Name:</label>
        <input id="nameInput" type="text" name="name" />

        <label for="emailInput">Email:</label>
        <input id="emailInput" type="email" name="email" />

        <button type="submit">Submit</button>
        <a href="https://example.com" id="externalLink">Go to Example</a>
      </form>

      <script>
        let formDirty = false;
        const form = document.getElementById('testForm');
        const inputs = form.querySelectorAll('input');

        inputs.forEach(input => {
          input.addEventListener('change', () => {
            formDirty = true;
          });
        });

        window.addEventListener('beforeunload', (e) => {
          if (formDirty) {
            e.preventDefault();
            e.returnValue = '';
            return '';
          }
        });

        form.addEventListener('submit', (e) => {
          e.preventDefault();
          formDirty = false;
          alert('Form submitted successfully');
        });
      </script>
    `);
  });

  test('should not show warning when navigating away from clean form', async ({ page }) => {
    const externalLink = page.getByRole('link', { name: 'Go to Example' });

    let dialogShown = false;
    page.on('dialog', async (dialog) => {
      dialogShown = true;
      await dialog.dismiss();
    });

    await externalLink.click();

    expect(dialogShown).toBe(false);
  });

  test('should show warning when navigating away from dirty form', async ({ page }) => {
    const nameInput = page.getByLabel('Name:');

    await nameInput.fill('John Doe');

    let dialogShown = false;
    let dialogMessage = '';

    page.on('dialog', async (dialog) => {
      dialogShown = true;
      dialogMessage = dialog.message();
      await dialog.dismiss();
    });

    await page.evaluate(() => {
      window.location.href = 'https://example.com';
    });

    expect(dialogShown).toBe(true);
  });

  test('should clear dirty state after form submission', async ({ page }) => {
    const nameInput = page.getByLabel('Name:');
    const submitButton = page.getByRole('button', { name: 'Submit' });

    await nameInput.fill('Jane Doe');

    page.on('dialog', async (dialog) => {
      await dialog.dismiss();
    });

    await submitButton.click();

    page.on('dialog', async (dialog) => {
      throw new Error('Dialog should not appear after form submission');
    });

    await page.evaluate(() => {
      window.location.href = 'https://example.com';
    });
  });

  test('should show warning when multiple fields are modified', async ({ page }) => {
    const nameInput = page.getByLabel('Name:');
    const emailInput = page.getByLabel('Email:');

    await nameInput.fill('John Doe');
    await emailInput.fill('john@example.com');

    let dialogShown = false;

    page.on('dialog', async (dialog) => {
      dialogShown = true;
      await dialog.dismiss();
    });

    await page.evaluate(() => {
      window.location.href = 'https://example.com';
    });

    expect(dialogShown).toBe(true);
  });

  test('should allow navigation when user confirms in warning dialog', async ({ page }) => {
    const nameInput = page.getByLabel('Name:');

    await nameInput.fill('John Doe');

    let navigationAllowed = false;

    page.on('dialog', async (dialog) => {
      navigationAllowed = true;
      await dialog.accept();
    });

    await page.evaluate(() => {
      window.location.href = 'https://example.com';
    });

    expect(navigationAllowed).toBe(true);
  });
});
